const tgData = $('Telegram Trigger').first().json;
const text = (tgData.message && tgData.message.text ? tgData.message.text : '').toLowerCase().trim();
const chatId = String(tgData.message && tgData.message.chat ? tgData.message.chat.id : '');
const state = $input.first().json;
const today = new Date().toLocaleDateString('en-MY', { day: 'numeric', month: 'long', year: 'numeric' });

function fmt(n) { return (n || 0).toFixed(2); }

function healthReport() {
  const careTasks = state.kai_care_tasks || [];
  const medications = state.kai_medications || [];
  const appointments = state.kai_appointments || [];
  const householdTasks = state.kai_household_tasks || [];
  const careCompleted = careTasks.filter(function(t) { return t.logs && t.logs.length > 0; }).length;
  const careTotal = careTasks.length;
  const medTotal = medications.reduce(function(s, m) { return s + (m.schedules ? m.schedules.length : 0); }, 0);
  const medTaken = medications.reduce(function(s, m) { return s + (m.schedules ? m.schedules.filter(function(sc) { return sc.taken; }).length : 0); }, 0);
  const medPct = medTotal > 0 ? Math.round((medTaken / medTotal) * 100) : 0;
  const houseCompleted = householdTasks.filter(function(t) { return t.logs && t.logs.length > 0; }).length;
  const houseTotal = householdTasks.length;
  const now = new Date();
  const future = appointments.filter(function(a) { return new Date(a.date + 'T' + a.time) >= now; });
  future.sort(function(a, b) { return a.date.localeCompare(b.date); });
  const nextAppt = future[0];
  const overallScore = Math.round((careTotal > 0 ? (careCompleted / careTotal) * 40 : 0) + (medTotal > 0 ? (medPct / 100) * 40 : 0) + (houseTotal > 0 ? (houseCompleted / houseTotal) * 20 : 0));
  const hasData = careTotal > 0 || medTotal > 0 || appointments.length > 0 || houseTotal > 0;
  const lines = [
    '\u{1F4CA} KAI Health Report \u2014 ' + today,
    '',
    hasData ? 'Overall Score: ' + overallScore + '/100' : 'No data recorded yet',
    '',
    careTotal > 0 ? '\u{1F3E5} Patient Care: ' + careCompleted + '/' + careTotal + ' tasks done' : '\u{1F3E5} Patient Care: No tasks',
    medTotal > 0 ? '\u{1F48A} Medication: ' + medPct + '% (' + medTaken + '/' + medTotal + ' doses taken)' : '\u{1F48A} Medication: No medications',
    nextAppt ? '\u{1F4C5} Next Appointment: ' + nextAppt.hospital + ' \u2014 ' + nextAppt.date : '\u{1F4C5} No upcoming appointments',
    houseTotal > 0 ? '\u{1F3E0} Household: ' + houseCompleted + '/' + houseTotal + ' tasks done' : '\u{1F3E0} Household: No tasks',
    '',
    '\u2014 KAI Caregiving App'
  ];
  return lines.join('\n');
}

function financialReport() {
  const householdTasks = state.kai_household_tasks || [];
  const appointments = state.kai_appointments || [];
  let groceryTotal = 0;
  let medicalTotal = 0;
  const groceryLines = [];
  const medicalLines = [];
  const groceries = householdTasks.find(function(t) { return t.id === 'groceries'; });
  if (groceries && groceries.logs) {
    groceries.logs.forEach(function(log) {
      if (!log.receipt) return;
      groceryTotal += log.receipt.total || 0;
      groceryLines.push('  \u2022 ' + (log.receipt.store || 'Grocery') + ' \u2014 ' + (log.receipt.currency || 'MYR') + ' ' + fmt(log.receipt.total));
    });
  }
  appointments.forEach(function(a) {
    if (!a.doc || !a.doc.report) return;
    const r = a.doc.report;
    medicalTotal += r.total || 0;
    medicalLines.push('  \u2022 ' + (r.hospital || a.hospital) + ' \u2014 ' + (r.currency || 'MYR') + ' ' + fmt(r.total));
  });
  const grandTotal = groceryTotal + medicalTotal;
  const lines = [
    '\u{1F4B0} KAI Financial Report \u2014 ' + today,
    '',
    'Total Expenses: MYR ' + fmt(grandTotal),
    '  \u{1F6D2} Groceries: MYR ' + fmt(groceryTotal),
    '  \u{1F3E5} Medical: MYR ' + fmt(medicalTotal)
  ];
  if (groceryLines.length > 0) { lines.push(''); lines.push('Grocery receipts:'); groceryLines.forEach(function(l) { lines.push(l); }); }
  if (medicalLines.length > 0) { lines.push(''); lines.push('Medical receipts:'); medicalLines.forEach(function(l) { lines.push(l); }); }
  lines.push('');
  lines.push('\u2014 KAI Caregiving App');
  return lines.join('\n');
}

function helpMessage() {
  return [
    '\u{1F916} KAI Bot \u2014 Commands',
    '',
    '\u{1F4CA} health \u2014 Health & care report',
    '\u{1F4B0} financial \u2014 Expense report',
    '',
    'Just type a keyword and I will send you the latest report.',
    '',
    '\u2014 KAI Caregiving App'
  ].join('\n');
}

let message;
if (text.includes('health') || text.includes('care') || (text.includes('report') && !text.includes('financial') && !text.includes('expense'))) {
  message = healthReport();
} else if (text.includes('financial') || text.includes('finance') || text.includes('expense') || text.includes('money') || text.includes('cost')) {
  message = financialReport();
} else {
  message = helpMessage();
}

return [{ json: { message: message, chatId: chatId } }];
